Un robot sube una cuesta en saltos de 1, 2 o 3 metros y se quiere saber de cuántas formas llega arriba.

function caminosCuesta(m) {
  const f = [1];
  for (let i = 1; i <= m; i++) {
    f[i] = f[i - 1];
    if (i >= 2) f[i] += f[i - 2];
    if (i >= 3) f[i] += f[i - 3];
  }
  return f[m];
}
